            aIngress = (RotL64(aWaterLaneA[((aIndex + 11418U)) & S_BLOCK1], 47U) ^ RotL64(aWindLaneC[((aIndex + 15870U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aPoisonLaneA[((aIndex + 15680U)) & S_BLOCK1], 23U) ^ RotL64(aFireLaneB[((aIndex + 13926U)) & S_BLOCK1], 58U));
