            //
            aWandererD = aWandererD + (((RotL64(aCross, 37U) + RotL64(aOrbiterJ, 12U)) + aOrbiterD) + aPhaseAWandererUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1]);
