            aWandererI = aWandererI + ((((RotL64(aIngress, 43U) + RotL64(aOrbiterH, 29U)) + aOrbiterK) + RotL64(aCarry, 37U)) + aPhaseAWandererUpdateSaltD[((aIndex + 19U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 29U) + RotL64(aOrbiterG, 57U)) + aOrbiterK);
            aWandererG = aWandererG + (((RotL64(aCross, 19U) + aOrbiterJ) + RotL64(aOrbiterH, 47U)) + RotL64(aCarry, 23U));
