            aOrbiterK = ((aWandererE + RotL64(aPrevious, 13U)) + 0x4E7957C6E4CAC90FULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 57U)) + 0x59D9BD926515A7AEULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
