            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xCFABE89DF6E5112BULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0x060D7C9C238F52BAULL) ^ aPhaseAOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
