            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0xBBC9011E1884B82EULL) + aPhaseAOrbiterUpdateSaltD[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xA75EA8950353F9F1ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9B77763E21A0409BULL), 35U);
