            aOrbiterG = ((aWandererB + RotL64(aCross, 43U)) + RotL64(aCarry, 37U)) + 0x28F101F07C165246ULL;
            aOrbiterH = ((aWandererA + RotL64(aScatter, 10U)) + 0x47C381C1DDD6C973ULL) + aPhaseDOrbiterAssignSaltC[((aIndex + 3U)) & S_SALT1];
            aOrbiterJ = (aWandererJ + RotL64(aCross, 35U)) + 0x8FE1753F0227AB2BULL;
            aOrbiterI = ((aWandererK + RotL64(aIngress, 3U)) + 0x3E06E7F416B587F6ULL) + aPhaseDOrbiterAssignSaltF[((aIndex + 19U)) & S_SALT1];
