            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0x44709E746A90B759ULL) + aPhaseCOrbiterUpdateSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xBF6FC613B88D5DDCULL;
